<?php session_start(); include "config.php"; $id=(int)($_GET["id"]??0); $stmt=mysqli_prepare($conn,"SELECT * FROM courses WHERE id=?"); mysqli_stmt_bind_param($stmt,"i",$id); mysqli_stmt_execute($stmt); $course=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); include "includes/header.php"; include "includes/navbar.php"; ?>
<div class="container py-5"><?php if($course){ ?><div class="detail-card shadow"><div class="row g-0"><div class="col-md-6"><img src="images/<?php echo htmlspecialchars($course["image"]); ?>" class="detail-img"></div><div class="col-md-6 p-5"><span class="badge bg-primary mb-3"><?php echo htmlspecialchars($course["duration"]); ?></span><h1><?php echo htmlspecialchars($course["course_name"]); ?></h1><p class="text-muted fs-5"><?php echo htmlspecialchars($course["description"]); ?></p><h2 class="text-primary mb-4">₹<?php echo number_format($course["fees"],2); ?></h2><?php if(isset($_SESSION["student_id"])){ ?><a href="register_course.php?id=<?php echo $course["id"]; ?>" class="btn btn-success btn-lg">Register Course</a><?php }else{ ?><a href="login.php" class="btn btn-primary btn-lg">Login to Register</a><?php } ?></div></div></div><?php }else echo '<div class="alert alert-danger">Course not found.</div>'; ?></div>
